      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "Is the drummer adjusting his in-ear monitor mix?", textHi: "क्या ड्रमर अपने कान वाले ईयरफ़ोन में आवाज़ की सेटिंग ठीक कर रहे हैं?" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "Yes, he is asking for more bass guitar and less snare drum in his left ear channel.", textHi: "हाँ, वे अपने बाएँ कान में बास गिटार की ज़्यादा और ड्रम की कम आवाज़ मांग रहे हैं।" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "I am sending that adjustment to the auxiliary monitor board immediately.", textHi: "मैं तुरंत मिक्सिंग बोर्ड पर यह बदलाव करवाती हूँ।" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "The pyrotechnics technician is arming the cold spark fountains at the front edge of the stage.", textHi: "आतिशबाज़ी तकनीशियन स्टेज के आगे वाले हिस्से में ठंडी चिंगारी वाले फ़व्वारे सेट कर रहे हैं।" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "Ensure he is maintaining all safety clearances from the audience barrier.", textHi: "सुनिश्चित करें कि वे दर्शकों की बैरिकेडिंग से पूरी सुरक्षित दूरी बनाए रखें।" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "All safety interlocks are showing green on his remote detonator box.", textHi: "उनके रिमोट बॉक्स पर सभी सुरक्षा बत्तियाँ हरी जल रही हैं।" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "Look at the stadium gates! Security is opening the main turnstiles and fans are pouring in!", textHi: "स्टेडियम के गेट देखिए! सुरक्षा गार्ड मुख्य गेट खोल रहे हैं और दर्शक अंदर उमड़ रहे हैं!" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "Twenty thousand fans are chanting the band's name in unison!", textHi: "बीस हज़ार दर्शक एक सुर में बैंड का नाम पुकार रहे हैं!" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "The energy out there is electrifying! Is the keyboard player ready with his synth presets?", textHi: "बाहर का माहौल बहुत रोमांचक है! क्या कीबोर्ड वादक अपनी धुनों के साथ तैयार हैं?" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "He is loading the grand piano sample library into his synthesizer right now.", textHi: "वे अभी अपने कीबोर्ड में पियानो के सुर लोड कर रहे हैं।" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "Makeup artists are doing final touch-ups on the band members in green room two.", textHi: "मेकअप आर्टिस्ट दो नंबर ग्रीन रूम में कलाकारों का अंतिम टच-अप कर रहे हैं।" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "The band is gathering in a pre-show huddle and putting their hands together.", textHi: "बैंड के सभी सदस्य एक घेरे में खड़े होकर एक-दूसरे का हाथ थाम रहे हैं।" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "Two minutes to house lights going dark! Standby, audio and video teams!", textHi: "हॉल की लाइटें बंद होने में दो मिनट बाकी! ऑडियो और वीडियो टीम, तैयार रहिए!" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "Visual projection is streaming the opening cinematic intro on the giant LED wall.", textHi: "बड़ी एलईडी स्क्रीन पर शुरुआती वीडियो का प्रसारण शुरू हो रहा है।" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "Dimming arena lights in three, two, one... Curtains rising!", textHi: "तीन, दो, एक... लाइटें मद्धिम, पर्दा उठ रहा है!" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "The crowd is screaming with sheer euphoria! The guitar riffs are kicking in!", textHi: "दर्शकों का शोर गूँज उठा है! गिटार की पहली धुन शुरू हो रही है!" },
      { speaker: "Stage Manager Tanya", avatar: "🎧", textEn: "Have a phenomenal show, everyone! We are live!", textHi: "शानदार शो हो आप सभी का! शो लाइव हो चुका है!" },
      { speaker: "Sound Tech Neil", avatar: "🎛️", textEn: "Rock on!", textHi: "मज़ा आ गया!" }
